<?php
use App\Http\Controllers\Api\DashboardController; use App\Http\Controllers\Api\InventoryController; use App\Http\Controllers\Api\OrderController; use App\Http\Controllers\Api\ProductController; use Illuminate\Http\Request; use Illuminate\Support\Facades\Route;
Route::middleware('auth:sanctum')->group(function(){Route::get('/me',fn(Request $r)=>$r->user()->only(['id','name','email']));Route::get('/dashboard',DashboardController::class);Route::apiResource('products',ProductController::class);Route::get('/inventory/movements',[InventoryController::class,'index']);Route::post('/inventory/movements',[InventoryController::class,'store']);Route::apiResource('orders',OrderController::class);});
